12 | 
13 | const TYPE_LABELS: Record<ChallengeType, string> = {
14 |   daily: "Diarios",
15 |   weekly: "Semanales",
16 |   monthly: "Mensuales",
17 | };
18 | 
19 | const TYPE_COLORS: Record<ChallengeType, string> = {
20 |   daily: "text-success",
21 |   weekly: "text-blue",
22 |   monthly: "text-purple",
23 | };
24 | 
25 | const TYPE_BG: Record<ChallengeType, string> = {
26 |   daily: "bg-success-dim border-success/30",
27 |   weekly: "bg-blue-dim border-blue/30",
28 |   monthly: "bg-purple-dim border-purple/30",
29 | };
