31 | export default function RetosPage() {
32 |   const ready = useRequireOnboarding();
33 |   const challenges = useTitanStore((s) => s.challenges);
34 |   const [filter, setFilter] = useState<ChallengeType | "all">("all");
35 | 
36 |   if (!ready) return null;
37 | 
38 |   const filtered =
39 |     filter === "all" ? challenges : challenges.filter((c) => c.type === filter);
40 | 
41 |   const totalXp = challenges
42 |     .filter((c) => c.completed)
43 |     .reduce((sum, c) => sum + c.xpReward, 0);
44 | 
45 |   const completedCount = challenges.filter((c) => c.completed).length;
46 | 
47 |   return (
48 |     <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[110px]">
49 |       <ScreenHeader
50 |         title="Retos"
51 |         subtitle={`${completedCount}/${challenges.length} completados · +${totalXp} XP ganado`}
52 |       />
53 | 
54 |       {/* Resumen */}
55 |       <div className="flex gap-2.5">
56 |         {(["daily", "weekly", "monthly"] as ChallengeType[]).map((type) => {
57 |           const group = challenges.filter((c) => c.type === type);
58 |           const done = group.filter((c) => c.completed).length;
59 |           return (
60 |             <div
61 |               key={type}
62 |               className={`flex-1 rounded-[18px] border p-3.5 ${TYPE_BG[type]}`}
63 |             >
64 |               <div className={`text-[20px] font-extrabold tabular-nums ${TYPE_COLORS[type]}`}>
65 |                 {done}/{group.length}
66 |               </div>
67 |               <div className="mt-0.5 text-[10px] font-bold text-text-dim">
68 |                 {TYPE_LABELS[type]}
69 |               </div>
70 |             </div>
71 |           );
72 |         })}
73 |       </div>
74 | 
75 |       {/* Filtros */}
76 |       <div className="flex gap-2">
77 |         {(["all", "daily", "weekly", "monthly"] as (ChallengeType | "all")[]).map((f) => (
78 |           <button
79 |             key={f}
80 |             onClick={() => setFilter(f)}
81 |             className={`rounded-full px-4 py-2 text-[12px] font-bold transition-all ${
82 |               filter === f
83 |                 ? "bg-accent text-black"
84 |                 : "border border-border bg-glass text-text-dim"
85 |             }`}
86 |           >
87 |             {f === "all" ? "Todos" : TYPE_LABELS[f]}
88 |           </button>
89 |         ))}
90 |       </div>
91 | 
92 |       {/* Lista de retos */}
93 |       <div className="flex flex-col gap-3">
94 |         {filtered.map((challenge, i) => {
95 |           const pct = Math.min(
96 |             Math.round((challenge.progress / challenge.target) * 100),
97 |             100
98 |           );
99 |           return (
100 |             <motion.div
101 |               key={challenge.id}
102 |               initial={{ opacity: 0, y: 10 }}
103 |               animate={{ opacity: 1, y: 0 }}
104 |               transition={{ delay: i * 0.04 }}
105 |             >
106 |               <GlassCard
107 |                 className={`p-4 ${
108 |                   challenge.completed ? "border-accent/30 bg-accent-dim" : ""
109 |                 }`}
110 |               >
111 |                 <div className="flex items-start justify-between gap-3">
112 |                   <div className="min-w-0 flex-1">
113 |                     <div className="flex items-center gap-2">
114 |                       <span
115 |                         className={`text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full border ${TYPE_BG[challenge.type]} ${TYPE_COLORS[challenge.type]}`}
116 |                       >
117 |                         {TYPE_LABELS[challenge.type]}
118 |                       </span>
119 |                       {challenge.completed && (
120 |                         <span className="text-[10px] font-bold text-accent">✓ Completado</span>
121 |                       )}
122 |                     </div>
123 |                     <div className="mt-1.5 text-[15px] font-bold">{challenge.title}</div>
124 |                     <div className="mt-0.5 text-[12px] text-text-dim">
125 |                       {challenge.description}
126 |                     </div>
127 |                   </div>
128 |                   <div className="shrink-0 text-right">
129 |                     <div className="text-[14px] font-extrabold text-accent">
130 |                       +{challenge.xpReward}
131 |                     </div>
132 |                     <div className="text-[10px] text-text-dimmer">XP</div>
133 |                   </div>
134 |                 </div>
135 | 
136 |                 {/* Progress */}
137 |                 <div className="mt-3">
138 |                   <div className="mb-1 flex items-center justify-between">
139 |                     <span className="text-[11px] text-text-dim">
140 |                       {challenge.progress.toLocaleString("es")} / {challenge.target.toLocaleString("es")} {challenge.unit}
141 |                     </span>
142 |                     <span className="text-[11px] font-bold">{pct}%</span>
143 |                   </div>
144 |                   <div className="h-2 overflow-hidden rounded-full bg-white/10">
145 |                     <motion.div
146 |                       className={`h-full rounded-full ${challenge.completed ? "bg-accent" : "bg-white/40"}`}
147 |                       initial={{ width: 0 }}
148 |                       animate={{ width: `${pct}%` }}
149 |                       transition={{ duration: 0.8, ease: "easeOut" }}
150 |                     />
151 |                   </div>
152 |                 </div>
153 |               </GlassCard>
154 |             </motion.div>
155 |           );
156 |         })}
157 |       </div>
158 | 
159 |       <TabBar />
160 |     </div>
161 |   );
162 | }
